script:
"=== direct Zen API test ==="
$envContent = Get-Content "C:\Users\E\AppData\Local\hermes\.env" -Raw
$token = ($envContent -split "`n" | Where-Object { $_ -match "^OPENAI_API_KEY=" }) -replace "OPENAI_API_KEY=", ""
$token = $token.Trim()
"Token length: $($token.Length)"
try {
  $headers = @{ "Authorization" = "Bearer $token" }
  $resp = Invoke-WebRequest -Uri "https://opencode.ai/zen/v1/models" -Headers $headers -TimeoutSec 15 -UseBasicParsing
  "Models endpoint: $($resp.StatusCode) OK"
} catch {
  "Models failed: $($_.Exception.Message)"
}
